// Syncs branding.yaml into Dart + Android build config.
//
//   dart run tool/sync_branding.dart            write generated files
//   dart run tool/sync_branding.dart --check    verify they are up to date (CI)
//
// The generated Dart file is committed so a fresh clone builds without running
// this tool. `flutter test` asserts it still matches branding.yaml.
import 'dart:io';

import 'package:yaml/yaml.dart';

const _brandingYaml = 'branding.yaml';
const _dartOut = 'lib/src/app/branding.g.dart';
const _gradleProps = 'android/app/branding.properties';
const _androidValues = 'android/app/src/main/res/values/branding.xml';

void main(List<String> args) {
  final check = args.contains('--check');
  final yaml = loadYaml(File(_brandingYaml).readAsStringSync()) as YamlMap;
  final app = yaml['app'] as YamlMap;
  final name = app['name'] as String;
  final applicationId = app['application_id'] as String;
  final description = app['description'] as String;
  final wordmark = yaml['wordmark'] as String;

  final files = <String, String>{
    _dartOut: _dartContent(name, applicationId, description, wordmark),
    _gradleProps:
        '# Generated by tool/sync_branding.dart from branding.yaml. Do not edit.\n'
        'applicationId=$applicationId\n'
        'appName=$name\n',
    _androidValues:
        '<?xml version="1.0" encoding="utf-8"?>\n'
        '<!-- Generated by tool/sync_branding.dart from branding.yaml. -->\n'
        '<resources>\n'
        '    <string name="app_name">$name</string>\n'
        '</resources>\n',
  };

  var stale = false;
  files.forEach((path, content) {
    final file = File(path);
    final current = file.existsSync() ? file.readAsStringSync() : null;
    if (current == content) return;
    if (check) {
      stderr.writeln('out of date: $path (run: dart run tool/sync_branding.dart)');
      stale = true;
      return;
    }
    file.parent.createSync(recursive: true);
    file.writeAsStringSync(content);
    stdout.writeln('wrote $path');
  });

  if (stale) exit(1);
  stdout.writeln(check ? 'branding is up to date' : 'branding synced');
}

String _dartContent(
  String name,
  String applicationId,
  String description,
  String wordmark,
) =>
    '''
// Generated by tool/sync_branding.dart from branding.yaml. Do not edit by hand;
// run `dart run tool/sync_branding.dart` after changing branding.yaml.
// Keep in sync with test/tool/branding_sync_test.dart.

/// The user-facing app name.
const String kAppName = '$name';

/// Android application id / bundle id placeholder.
const String kApplicationId = '$applicationId';

/// One-line description used in stores and About.
const String kAppDescription = '$description';

/// Neutral wordmark shown in the top bar.
const String kWordmark = '$wordmark';
''';
